targets.query:
from(bucket: "${bucket}") |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "task" and r._field == "energy_j") |> filter(fn: (r) => r.scenario =~ /^${scenario:regex}$/ and r.method =~ /^${method:regex}$/ and r.run_id =~ /^${run_id:regex}$/)
  |> group(columns: ["method"]) |> aggregateWindow(every: 5s, fn: mean)

from(bucket: "${bucket}") |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "zone" and r._field == "rho" and r.slot_type == "gpu") |> filter(fn: (r) => r.scenario =~ /^${scenario:regex}$/ and r.method =~ /^${method:regex}$/ and r.run_id =~ /^${run_id:regex}$/)
  |> group(columns: ["method", "zone"]) |> aggregateWindow(every: 1s, fn: mean)

from(bucket: "${bucket}") |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "pipe" and r._field == "wait_s") |> filter(fn: (r) => r.scenario =~ /^${scenario:regex}$/ and r.method =~ /^${method:regex}$/ and r.run_id =~ /^${run_id:regex}$/)
  |> group(columns: ["method", "pipe"]) |> aggregateWindow(every: 1s, fn: max)

from(bucket: "${bucket}") |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "zone" and r._field == "refusals") |> filter(fn: (r) => r.scenario =~ /^${scenario:regex}$/ and r.method =~ /^${method:regex}$/ and r.run_id =~ /^${run_id:regex}$/)
  |> group(columns: ["method"]) |> aggregateWindow(every: 1s, fn: sum)

from(bucket: "${bucket}") |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "learning" and (r._field == "td_loss" or r._field == "demo_upsample_ratio")) |> filter(fn: (r) => r.scenario =~ /^${scenario:regex}$/ and r.method =~ /^${method:regex}$/ and r.run_id =~ /^${run_id:regex}$/)
  |> group(columns: ["zone", "_field"])
